  1 | import { useCallback, useRef, useState, useEffect } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import { useTauri } from "./hooks/useTauri";
  5 | import { useAudioVisualizer } from "./hooks/useAudioVisualizer";
  6 | import { useFavorites } from "./hooks/useFavorites";
  7 | import { useHistory } from "./hooks/useHistory";
  8 | import { usePlaylists } from "./hooks/usePlaylists";
  9 | import { useTheme } from "./hooks/useTheme";
 10 | import {
 11 |   TitleBar,
 12 |   Playlist,
 13 |   PlayerControls,
 14 |   ProgressBar,
 15 |   StatusBar,
 16 |   DriveBrowser,
 17 |   AudioVisualizer,
 18 |   HistoryPanel,
 19 |   PlaylistManager,
 20 | } from "./components";
 21 | import type { Track } from "./types";
 22 | 
 23 | function App() {
 24 |   const {
 25 |     state,
 26 |     play,
 27 |     pause,
 28 |     next,
 29 |     prev,
 30 |     seek,
 31 |     setVolume,
 32 |     addTrack,
 33 |     toggleShuffle,
 34 |     reorderPlaylist,
 35 |     toggleFavorite,
 36 |     loadFavorites: loadPlayerFavorites,
 37 |     audioRef,
 38 |   } = usePlayerWithAudio([]);
 39 | 
 40 |   const { processFiles } = useMetadata();
 41 |   const {
 42 |     state: tauriState,
 43 |     openFilePicker,
 44 |     filePathToUrl,
 45 |     sendNotification,
 46 |     registerShortcuts,
 47 |   } = useTauri();
 48 | 
 49 |   const { loadFavorites } = useFavorites();
 50 |   const history = useHistory();
 51 |   const playlists = usePlaylists();
 52 |   const { theme, cycleTheme } = useTheme();
 53 | 
 54 |   const [isLoading, setIsLoading] = useState(false);
 55 |   const [loadingProgress, setLoadingProgress] = useState<{ processed: number; total: number } | null>(null);
 56 |   const [showDrive, setShowDrive] = useState(false);
 57 |   const [showHistory, setShowHistory] = useState(false);
 58 |   const [showPlaylistManager, setShowPlaylistManager] = useState(false);
 59 |   const [isCompact, setIsCompact] = useState(false);
 60 | 
 61 |   const fileInputRef = useRef<HTMLInputElement>(null);
 62 | 
 63 |   // Carrega favoritos salvos ao iniciar
 64 |   useEffect(() => {
 65 |     const savedFavorites = loadFavorites();
 66 |     if (savedFavorites.length > 0) {
 67 |       loadPlayerFavorites(savedFavorites);
 68 |     }
 69 |     // eslint-disable-next-line react-hooks/exhaustive-deps
 70 |   }, []);
 71 | 
 72 |   // Registra atalhos de teclado (Media Session API + Tauri global shortcuts)
 73 |   useEffect(() => {
 74 |     const cleanup = registerShortcuts({
 75 |       MediaPlayPause: () => (state.isPlaying ? pause() : play()),
 76 |       MediaNextTrack: () => next(),
 77 |       MediaPrevTrack: () => prev(),
 78 |       MediaStop: () => pause(),
 79 |     });
 80 | 
 81 |     return () => {
 82 |       cleanup.then((fn) => fn());
 83 |     };
 84 |   }, [registerShortcuts, state.isPlaying, pause, play, next, prev]);
 85 | 
 86 |   // Media Session API (navegador)
 87 |   useEffect(() => {
 88 |     if (!("mediaSession" in navigator)) return;
 89 | 
 90 |     navigator.mediaSession.metadata = new MediaMetadata({
 91 |       title: state.currentTrack?.title ?? "Llama Player",
 92 |       artist: state.currentTrack?.artist ?? undefined,
 93 |       album: state.currentTrack?.album ?? undefined,
 94 |     });
 95 | 
 96 |     navigator.mediaSession.setActionHandler("play", () => play());
 97 |     navigator.mediaSession.setActionHandler("pause", () => pause());
 98 |     navigator.mediaSession.setActionHandler("nexttrack", () => next());
 99 |     navigator.mediaSession.setActionHandler("previoustrack", () => prev());
100 |   }, [state.currentTrack, play, pause, next, prev]);
101 | 
102 |   // Notificação ao trocar de música + histórico
103 |   useEffect(() => {
104 |     if (state.currentTrack && state.isPlaying) {
105 |       sendNotification(
106 |         `▶ ${state.currentTrack.title}`,
107 |         state.currentTrack.artist
108 |           ? `Por ${state.currentTrack.artist}`
109 |           : undefined
110 |       );
111 |       history.addEntry(state.currentTrack);
112 |     }
113 |   }, [state.currentTrack?.id, state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
114 | 
115 |   const visualizer = useAudioVisualizer(audioRef, state.isPlaying);
116 | 
117 |   const handleSelectTrack = (track: Track) => {
118 |     play(track);
119 |   };
120 | 
121 |   const handleOpenFile = async () => {
122 |     if (tauriState.isTauri) {
123 |       // Usa file picker nativo do Tauri
124 |       setIsLoading(true);
125 |       try {
126 |         const paths = await openFilePicker();
127 |         if (!paths || paths.length === 0) return;
128 | 
129 |         // Converte paths para File objects (via fetch do asset protocol)
130 |         const tracks: Track[] = [];
131 |         for (const path of paths) {
132 |           const url = await filePathToUrl(path);
133 |           const name = path.split(/[/\\]/).pop() || path;
134 |           tracks.push({
135 |             id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
136 |             title: name.replace(/\.[^/.]+$/, ""),
137 |             duration: 0,
138 |             src: url,
139 |           });
140 |         }
141 | 
142 |         for (const track of tracks) {
143 |           addTrack(track);
144 |         }
145 | 
146 |         if (!state.currentTrack && tracks.length > 0) {
147 |           play(tracks[0]);
148 |         }
149 |       } catch (err) {
150 |         console.error("[Llama Player] Erro ao abrir arquivos:", err);
151 |       } finally {
152 |         setIsLoading(false);
153 |       }
154 |     } else {
155 |       // Fallback: input file HTML
156 |       fileInputRef.current?.click();
157 |     }
158 |   };
159 | 
160 |   const handleFileChange = useCallback(
161 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
162 |       const files = e.target.files;
163 |       if (!files || files.length === 0) return;
164 | 
165 |       setIsLoading(true);
166 |       setLoadingProgress(null);
167 | 
168 |       try {
169 |         const fileArray = Array.from(files);
170 |         const tracks = await processFiles(fileArray, (progress) => {
171 |           setLoadingProgress(progress);
172 |         });
173 | 
174 |         for (const track of tracks) {
175 |           addTrack(track);
176 |         }
177 | 
178 |         // If nothing is playing, start with the first track
179 |         if (!state.currentTrack && tracks.length > 0) {
180 |           play(tracks[0]);
181 |         }
182 |       } catch (err) {
183 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
184 |       } finally {
185 |         setIsLoading(false);
186 |         setLoadingProgress(null);
187 |       }
188 | 
189 |       // Reset input so the same file can be selected again
190 |       e.target.value = "";
191 |     },
192 |     [processFiles, addTrack, state.currentTrack, play]
193 |   );
194 | 
195 |   const handleDropFiles = useCallback(
196 |     async (files: FileList) => {
197 |       setIsLoading(true);
198 |       setLoadingProgress(null);
199 |       try {
200 |         const fileArray = Array.from(files);
201 |         const tracks = await processFiles(fileArray, (progress) => {
202 |           setLoadingProgress(progress);
203 |         });
204 |         for (const track of tracks) {
205 |           addTrack(track);
206 |         }
207 |         if (!state.currentTrack && tracks.length > 0) {
208 |           play(tracks[0]);
209 |         }
210 |       } catch (err) {
211 |         console.error("[Llama Player] Erro ao processar arquivos arrastados:", err);
212 |       } finally {
213 |         setIsLoading(false);
214 |         setLoadingProgress(null);
215 |       }
216 |     },
217 |     [processFiles, addTrack, state.currentTrack, play]
218 |   );
219 | 
220 |   const handleAddDriveTracks = useCallback(
221 |     (tracks: Track[]) => {
222 |       for (const track of tracks) {
223 |         addTrack(track);
224 |       }
225 |       if (!state.currentTrack && tracks.length > 0) {
226 |         play(tracks[0]);
227 |       }
228 |     },
229 |     [addTrack, state.currentTrack, play]
230 |   );
231 | 
232 |   return (
233 |     <div className="app">
234 |       <TitleBar />
235 | 
236 |       <main className="main-content">
237 |         <div className="toolbar">
238 |           <button
239 |             className="toolbar-btn"
240 |             onClick={handleOpenFile}
241 |             disabled={isLoading}
242 |             title="Abrir arquivo de áudio local"
243 |           >
244 |             {isLoading && loadingProgress
245 |               ? `⏳ ${loadingProgress.processed}/${loadingProgress.total}`
246 |               : isLoading
247 |               ? "⏳ Lendo..."
248 |               : "📂 Arquivo local"}
249 |           </button>
250 |           <input
251 |             ref={fileInputRef}
252 |             type="file"
253 |             accept="audio/*"
254 |             multiple
255 |             style={{ display: "none" }}
256 |             onChange={handleFileChange}
257 |           />
258 |           <button
259 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
260 |             onClick={() => setShowDrive((v) => !v)}
261 |             title="Google Drive"
262 |           >
263 |             ☁️ Drive
264 |           </button>
265 |           <button
266 |             className={`toolbar-btn ${showHistory ? "toolbar-btn-active" : ""}`}
267 |             onClick={() => setShowHistory((v) => !v)}
268 |             title="Histórico de reprodução"
269 |           >
270 |             🕐 Histórico
271 |           </button>
272 |           <button
273 |             className={`toolbar-btn ${showPlaylistManager ? "toolbar-btn-active" : ""}`}
274 |             onClick={() => setShowPlaylistManager((v) => !v)}
275 |             title="Gerenciar playlists"
276 |           >
277 |             📋 Playlists
278 |           </button>
279 |           <button
280 |             className="toolbar-btn"
281 |             onClick={cycleTheme}
282 |             title={`Tema: ${theme === "winamp" ? "Winamp Nostálgico" : theme === "dark" ? "Escuro" : "Claro"}`}
283 |           >
284 |             {theme === "winamp" ? "🎨" : theme === "dark" ? "🌙" : "☀️"}
285 |           </button>
286 |         </div>
287 | 
288 |         {showDrive && (
289 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
290 |         )}
291 | 
292 |         {showHistory && (
293 |           <HistoryPanel
294 |             entries={history.entries}
295 |             onSelectTrack={handleSelectTrack}
296 |             onClear={history.clear}
297 |           />
298 |         )}
299 | 
300 |         {showPlaylistManager && (
301 |           <PlaylistManager
302 |             playlists={playlists.playlists}
303 |             activePlaylistId={playlists.activePlaylistId}
304 |             currentTracks={state.playlist}
305 |             onSavePlaylist={playlists.saveCurrentPlaylist}
306 |             onLoadPlaylist={playlists.loadPlaylist}
307 |             onDeletePlaylist={playlists.deletePlaylist}
308 |             onRenamePlaylist={playlists.renamePlaylist}
309 |             onReplaceTracks={(tracks) => {
310 |               // Replace entire playlist
311 |               // First clear by reordering to empty, then add tracks
312 |               // We use a workaround: reorder to empty then add each track
313 |               // Actually, let's just load the tracks into the playlist
314 |               // by reordering to the saved tracks
315 |               if (tracks.length === 0) return;
316 |               // We need to replace the playlist. Since we have reorderPlaylist,
317 |               // we can set the playlist to the loaded tracks directly.
318 |               // The cleanest approach: reorder to the loaded tracks.
319 |               reorderPlaylist(tracks);
320 |               // Start playing the first track
321 |               play(tracks[0]);
322 |             }}
323 |             onClose={() => setShowPlaylistManager(false)}
324 |           />
325 |         )}
326 | 
327 |         <Playlist
328 |           tracks={state.playlist}
329 |           currentTrackId={state.currentTrack?.id ?? null}
330 |           isPlaying={state.isPlaying}
331 |           onSelectTrack={handleSelectTrack}
332 |           onReorderPlaylist={reorderPlaylist}
333 |           onDropFiles={handleDropFiles}
334 |           onToggleFavorite={toggleFavorite}
335 |         />
336 | 
337 |         <PlayerControls
338 |           currentTrack={state.currentTrack}
339 |           currentTrackId={state.currentTrack?.id ?? null}
340 |           isPlaying={state.isPlaying}
341 |           isShuffled={state.isShuffled}
342 |           isCompact={isCompact}
343 |           onPlay={() => play()}
344 |           onPause={pause}
345 |           onNext={next}
346 |           onPrev={prev}
347 |           onToggleShuffle={toggleShuffle}
348 |           onToggleFavorite={toggleFavorite}
349 |           onToggleCompact={() => setIsCompact((v) => !v)}
350 |         />
351 | 
352 |         <AudioVisualizer
353 |           frequencyData={visualizer.frequencyData}
354 |           waveformData={visualizer.waveformData}
355 |           isActive={visualizer.isActive}
356 |         />
357 | 
358 |         <ProgressBar
359 |           currentTime={state.currentTime}
360 |           duration={state.duration}
361 |           onSeek={seek}
362 |         />
363 |       </main>
364 | 
365 |       <StatusBar
366 |         isPlaying={state.isPlaying}
367 |         volume={state.volume}
368 |         onVolumeChange={setVolume}
369 |       />
370 |     </div>
371 |   );
372 | }
373 | 
374 | export default App;
